 20→// ParseExportSession parses export JSON content into an ExportSession structure.
 21→func ParseExportSession(data []byte) (*ExportSession, error) {
 22→	if len(data) == 0 {
 23→		return nil, nil //nolint:nilnil // nil for empty data is expected
 24→	}
 25→
 26→	var session ExportSession
 27→	if err := json.Unmarshal(data, &session); err != nil {
 28→		return nil, fmt.Errorf("failed to parse export session: %w", err)
 29→	}
 30→
 31→	return &session, nil
 32→}
 33→
 34→// SliceFromMessage returns an OpenCode export transcript scoped to messages starting from
 35→// startMessageIndex. This is the OpenCode equivalent of transcript.SliceFromLine —
 36→// for OpenCode's JSON format, scoping is done by message index rather than line offset.
 37→// Returns the original data if startMessageIndex <= 0.
 38→// Returns nil, nil if startMessageIndex exceeds the number of messages.
 39→func SliceFromMessage(data []byte, startMessageIndex int) ([]byte, error) {
 40→	if len(data) == 0 || startMessageIndex <= 0 {
 41→		return data, nil
 42→	}
 43→
 44→	session, err := ParseExportSession(data)
 45→	if err != nil {
 46→		return nil, fmt.Errorf("failed to parse export session for slicing: %w", err)
 47→	}
 48→	if session == nil {
 49→		return nil, nil
 50→	}
 51→
 52→	if startMessageIndex >= len(session.Messages) {
 53→		return nil, nil
 54→	}
 55→
 56→	scoped := &ExportSession{
 57→		Info:     session.Info,
 58→		Messages: session.Messages[startMessageIndex:],
 59→	}
 60→
 61→	out, err := json.Marshal(scoped)
 62→	if err != nil {
 63→		return nil, fmt.Errorf("failed to marshal scoped session: %w", err)
 64→	}
 65→	return out, nil
 66→}
