 68→// GetTranscriptPosition returns the number of messages in the transcript.
 69→func (a *OpenCodeAgent) GetTranscriptPosition(path string) (int, error) {
 70→	session, err := parseExportSessionFromFile(path)
 71→	if err != nil {
 72→		if os.IsNotExist(err) {
 73→			return 0, nil
 74→		}
 75→		return 0, err
 76→	}
 77→	if session == nil {
 78→		return 0, nil
 79→	}
 80→	return len(session.Messages), nil
 81→}
