 83→// ExtractModifiedFilesFromOffset extracts files modified by tool calls from the given message offset.
 84→func (a *OpenCodeAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
 85→	session, err := parseExportSessionFromFile(path)
 86→	if err != nil {
 87→		if os.IsNotExist(err) {
 88→			return nil, 0, nil
 89→		}
 90→		return nil, 0, err
 91→	}
 92→	if session == nil {
 93→		return nil, 0, nil
 94→	}
 95→
 96→	seen := make(map[string]bool)
 97→	var files []string
 98→
 99→	for i := startOffset; i < len(session.Messages); i++ {
100→		msg := session.Messages[i]
101→		if msg.Info.Role != roleAssistant {
102→			continue
103→		}
104→		for _, part := range msg.Parts {
105→			if part.Type != "tool" || part.State == nil {
106→				continue
107→			}
108→			if !slices.Contains(FileModificationTools, part.Tool) {
109→				continue
110→			}
111→			filePath := extractFilePathFromInput(part.State.Input)
112→			if filePath != "" && !seen[filePath] {
113→				seen[filePath] = true
114→				files = append(files, filePath)
115→			}
116→		}
117→	}
118→
119→	return files, len(session.Messages), nil
120→}
