158→// extractFilePathFromInput extracts the file path from an OpenCode tool's input map.
159→// OpenCode uses camelCase keys (e.g., "filePath"), with "path" as a fallback.
160→func extractFilePathFromInput(input map[string]any) string {
161→	for _, key := range []string{"filePath", "path"} {
162→		if v, ok := input[key]; ok {
163→			if s, ok := v.(string); ok && s != "" {
164→				return s
165→			}
166→		}
167→	}
168→	return ""
169→}
