171→// ExtractPrompts extracts user prompt strings from the transcript starting at the given offset.
172→func (a *OpenCodeAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
173→	session, err := parseExportSessionFromFile(sessionRef)
174→	if err != nil {
175→		if os.IsNotExist(err) {
176→			return nil, nil
177→		}
178→		return nil, err
179→	}
180→	if session == nil {
181→		return nil, nil
182→	}
183→
184→	var prompts []string
185→	for i := fromOffset; i < len(session.Messages); i++ {
186→		msg := session.Messages[i]
187→		if msg.Info.Role != roleUser {
188→			continue
189→		}
190→		// Extract text from parts
191→		content := ExtractTextFromParts(msg.Parts)
192→		if content != "" {
193→			prompts = append(prompts, content)
194→		}
195→	}
196→
