200→// ExtractSummary extracts the last assistant message content as a summary.
201→func (a *OpenCodeAgent) ExtractSummary(sessionRef string) (string, error) {
202→	session, err := parseExportSessionFromFile(sessionRef)
203→	if err != nil {
204→		if os.IsNotExist(err) {
205→			return "", nil
206→		}
207→		return "", err
208→	}
209→	if session == nil {
210→		return "", nil
211→	}
212→
213→	for i := len(session.Messages) - 1; i >= 0; i-- {
214→		msg := session.Messages[i]
215→		if msg.Info.Role == roleAssistant {
216→			content := ExtractTextFromParts(msg.Parts)
217→			if content != "" {
218→				return content, nil
219→			}
220→		}
221→	}
222→
223→	return "", nil
224→}
