226→// ExtractTextFromParts extracts text content from message parts.
227→func ExtractTextFromParts(parts []Part) string {
228→	var texts []string
229→	for _, part := range parts {
230→		if part.Type == "text" && part.Text != "" {
231→			texts = append(texts, part.Text)
232→		}
233→	}
234→	return strings.Join(texts, "\n")
235→}
