241→	if err != nil {
242→		return nil, err
243→	}
244→	if session == nil {
245→		return nil, nil
246→	}
247→
248→	var prompts []string
249→	for _, msg := range session.Messages {
250→		if msg.Info.Role != roleUser {
251→			continue
252→		}
253→		content := ExtractTextFromParts(msg.Parts)
254→		if content != "" {
