261→// CalculateTokenUsage computes token usage from assistant messages starting at the given offset.
262→func (a *OpenCodeAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
263→	session, err := ParseExportSession(transcriptData)
264→	if err != nil {
265→		if os.IsNotExist(err) {
266→			return nil, nil //nolint:nilnil // nil usage for nonexistent file is expected
267→		}
268→		return nil, fmt.Errorf("failed to parse transcript for token usage: %w", err)
269→	}
270→	if session == nil {
271→		return nil, nil //nolint:nilnil // nil usage for empty file is expected
272→	}
273→
274→	usage := &agent.TokenUsage{}
275→	for i := fromOffset; i < len(session.Messages); i++ {
276→		msg := session.Messages[i]
277→		if msg.Info.Role != roleAssistant || msg.Info.Tokens == nil {
278→			continue
279→		}
280→		usage.InputTokens += msg.Info.Tokens.Input
281→		usage.OutputTokens += msg.Info.Tokens.Output
282→		usage.CacheReadTokens += msg.Info.Tokens.Cache.Read
283→		usage.CacheCreationTokens += msg.Info.Tokens.Cache.Write
284→		usage.APICallCount++
285→	}
286→
287→	return usage, nil
288→}
