 8→func CalculateTokenUsage(ag Agent, transcriptData []byte, transcriptLinesAtStart int, subagentsDir string) *TokenUsage {
 9→	// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
10→	var tokenUsage *TokenUsage
11→	if subagentExtractor, ok := ag.(SubagentAwareExtractor); ok {
12→		usage, tokenErr := subagentExtractor.CalculateTotalTokenUsage(transcriptData, transcriptLinesAtStart, subagentsDir)
13→		if tokenErr != nil {
14→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage (with subagents): %v\n", tokenErr)
15→		} else {
16→			tokenUsage = usage
17→		}
18→	} else if calculator, ok := ag.(TokenCalculator); ok {
19→		// Fall back to basic token calculation (main transcript only)
20→		usage, tokenErr := calculator.CalculateTokenUsage(transcriptData, transcriptLinesAtStart)
21→		if tokenErr != nil {
22→			fmt.Fprintf(os.Stderr, "Warning: failed to calculate token usage: %v\n", tokenErr)
23→		} else {
24→			tokenUsage = usage
25→		}
26→	}
27→	return tokenUsage
28→}
