263→// SliceFromMessage returns a Gemini transcript scoped to messages starting from
264→// startMessageIndex. This is the Gemini equivalent of transcript.SliceFromLine —
265→// for Gemini's single JSON blob, scoping is done by message index rather than line offset.
266→// Returns the original data if startMessageIndex <= 0.
267→// Returns nil, nil if startMessageIndex exceeds the number of messages.
268→func SliceFromMessage(data []byte, startMessageIndex int) ([]byte, error) {
269→	if len(data) == 0 || startMessageIndex <= 0 {
270→		return data, nil
271→	}
272→
273→	t, err := ParseTranscript(data)
274→	if err != nil {
275→		return nil, fmt.Errorf("failed to parse transcript for slicing: %w", err)
276→	}
277→
278→	if startMessageIndex >= len(t.Messages) {
279→		return nil, nil
280→	}
281→
282→	scoped := &GeminiTranscript{
283→		Messages: t.Messages[startMessageIndex:],
284→	}
285→
286→	out, err := json.Marshal(scoped)
287→	if err != nil {
288→		return nil, fmt.Errorf("failed to marshal scoped transcript: %w", err)
289→	}
290→	return out, nil
291→}
