 51→	case HookNameBeforeTool, HookNameAfterTool, HookNameBeforeModel,
 52→		HookNameAfterModel, HookNameBeforeToolSelection, HookNameNotification:
 53→		// Acknowledged hooks with no lifecycle action
 54→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
