100→// CalculateTokenUsage computes token usage from the transcript starting at the given message offset.
101→func (g *GeminiCLIAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
102→	var transcript struct {
103→		Messages []geminiMessageWithTokens `json:"messages"`
104→	}
105→
106→	if err := json.Unmarshal(transcriptData, &transcript); err != nil {
107→		return &agent.TokenUsage{}, err
108→	}
109→
110→	usage := &agent.TokenUsage{}
111→
112→	for i, msg := range transcript.Messages {
113→		// Skip messages before startMessageIndex
114→		if i < fromOffset {
115→			continue
116→		}
117→
118→		// Only count tokens from gemini (assistant) messages
119→		if msg.Type != MessageTypeGemini {
120→			continue
121→		}
122→
123→		if msg.Tokens == nil {
124→			continue
125→		}
126→
127→		usage.APICallCount++
128→		usage.InputTokens += msg.Tokens.Input
129→		usage.OutputTokens += msg.Tokens.Output
130→		usage.CacheReadTokens += msg.Tokens.Cached
131→	}
132→
133→	return usage, nil
134→}
