132→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
133→	ref := o.shadowRef
134→	var hasShadowBranch bool
135→	if ref != nil {
136→		hasShadowBranch = true
137→	} else {
138→		refName := plumbing.NewBranchReferenceName(shadowBranchName)
139→		var err error
140→		ref, err = repo.Reference(refName, true)
141→		hasShadowBranch = err == nil
142→	}
143→
144→	var sessionData *ExtractedSessionData
145→	if hasShadowBranch {
146→		// Extract session data from the shadow branch (with live transcript fallback).
147→		// Use tracked files from session state instead of collecting all files from tree.
148→		// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini).
149→		// Pass live transcript path so condensation reads the current file rather than a
150→		// potentially stale shadow branch copy (SaveStep may have been skipped if the
151→		// last turn had no code changes).
152→		// Pass CheckpointTranscriptStart for accurate token calculation (line offset for Claude, message index for Gemini).
153→		var extractErr error
154→		sessionData, extractErr = s.extractSessionData(repo, ref.Hash(), state.SessionID, state.FilesTouched, state.AgentType, state.TranscriptPath, state.CheckpointTranscriptStart, state.Phase.IsActive())
155→		if extractErr != nil {
156→			return nil, fmt.Errorf("failed to extract session data: %w", extractErr)
157→		}
158→	} else {
159→		// No shadow branch: mid-session commit before Stop/SaveStep.
160→		// Extract data directly from live transcript.
161→		if state.TranscriptPath == "" {
162→			return nil, errors.New("shadow branch not found and no live transcript available")
163→		}
